cat << 'EOF' > fuseclient/src/main.rs
use fuser::{FileAttr, FileType, Filesystem, ReplyAttr, ReplyCreate, ReplyData, ReplyDirectory, ReplyEmpty, ReplyEntry, ReplyWrite, Request};
use reqwest::Client;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::ffi::OsStr;
use std::path::PathBuf;
use std::sync::{mpsc, Arc, Mutex};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};
use tokio::sync::oneshot;

[derive(Debug, Clone, Serialize, Deserialize)]
struct FileMeta {
    path: String,
    name: String,
    size: u64,
    is_dir: bool,
    mode: u32,
    atime: u64,
    mtime: u64,
    ctime: u64,
}

enum FsTask {
    GetAttr {
        path: String,
        reply: oneshot::Sender<Result<FileMeta, i32>>,
    },
    ReadDir {
        path: String,
        reply: oneshot::Sender<Result<Vec<FileMeta>, i32>>,
    },
    Read {
        path: String,
        offset: u64,
        size: u32,
        reply: oneshot::Sender<Result<Vec<u8>, i32>>,
    },
    Write {
        path: String,
        offset: u64,
         Vec<u8>,
        reply: oneshot::Sender<Result<u64, i32>>,
    },
    Create {
        parent: String,
        name: String,
        mode: u32,
        is_dir: bool,
        reply: oneshot::Sender<Result<FileMeta, i32>>,
    },
    Unlink {
        parent: String,
        name: String,
        is_dir: bool,
        reply: oneshot::Sender<Result<(), i32>>,
    },
}

struct CloudFs {
    cache: Arc<Mutex<HashMap<String, (FileMeta, Instant)>>>,
    dir_cache: Arc<Mutex<HashMap<String, (Vec<FileMeta>, Instant)>>>,
    ino_map: Arc<Mutex<HashMap<u64, String>>>,
    path_map: Arc<Mutex<HashMap<String, u64>>>,
    next_ino: Arc<Mutex<u64>>,
    task_tx: mpsc::Sender<FsTask>,
}

impl CloudFs {
    fn new(base_url: String, token: String, traceparent: String) > Self {
        let cache = Arc::new(Mutex::new(HashMap::new()));
        let dir_cache = Arc::new(Mutex::new(HashMap::new()));
        let ino_map = Arc::new(Mutex::new(HashMap::new()));
        let path_map = Arc::new(Mutex::new(HashMap::new()));
        let next_ino = Arc::new(Mutex::new(1u64));
        let (tx, rx) = mpsc::channel::<FsTask>();

        let client = Client::new();
        let base_url_clone = base_url.clone();
        let token_clone = token.clone();
        let traceparent_clone = traceparent.clone();

        std::thread::spawn(move || {
            let rt = tokio::runtime::Runtime::new().unwrap();
            rt.block_on(async move {
                loop {
                    match rx.recv() {
                        Ok(task) => {
                            let client = client.clone();
                            let base_url = base_url_clone.clone();
                            let token = token_clone.clone();
                            let traceparent = traceparent_clone.clone();
                            tokio::spawn(async move {
                                match task {
                                    FsTask::GetAttr { path, reply } => {
                                        let url = format!("{}/meta{}", base_url, path);
                                        let res = client.get(&url).header("Authorization", format!("Bearer {}", token)).header("traceparent", &traceparent).send().await;
                                        match res {
                                            Ok(r) if r.status().is_success() => {
                                                if let Ok(meta) = r.json::<FileMeta>().await {
                                                    let _ = reply.send(Ok(meta));
                                                } else { let _ = reply.send(Err(libc::EIO)); }
                                            },
                                            _ => { let _ = reply.send(Err(libc::ENOENT)); }
                                        }
                                    },
                                    FsTask::ReadDir { path, reply } => {
                                        let url = format!("{}/list{}", base_url, path);
                                        let res = client.get(&url).header("Authorization", format!("Bearer {}", token)).header("traceparent", &traceparent).send().await;
                                        match res {
                                            Ok(r) if r.status().is_success() => {
                                                if let Ok(metas) = r.json::<Vec<FileMeta>>().await {
                                                    let _ = reply.send(Ok(metas));
                                                } else { let _ = reply.send(Err(libc::EIO)); }
                                            },
                                            _ => { let _ = reply.send(Err(libc::ENOENT)); }
                                        }
                                    },
                                    FsTask::Read { path, offset, size, reply } => {
                                        let url = format!("{}/content{}", base_url, path);
                                        let res = client.get(&url).header("Authorization", format!("Bearer {}", token)).header("traceparent", &traceparent).header("Range", format!("bytes={}{}", offset, offset + size as u64  1)).send().await;
                                        match res {
                                            Ok(r) if r.status().is_success() || r.status().as_u16() == 206 => {
                                                match r.bytes().await {
                                                    Ok(b) => { let _ = reply.send(Ok(b.to_vec())); },
                                                    Err(_) => { let _ = reply.send(Err(libc::EIO)); }
                                                }
                                            },
                                            _ => { let _ = reply.send(Err(libc::EIO)); }
                                        }
                                    },
                                    FsTask::Write { path, offset: _, data, reply } => {
                                        let url = format!("{}/content{}", base_url, path);
                                        let res = client.put(&url).header("Authorization", format!("Bearer {}", token)).header("traceparent", &traceparent).body(data).send().await;
                                        match res {
                                            Ok(r) if r.status().is_success() => {
                                                if let Ok(meta) = r.json::<FileMeta>().await {
                                                    let _ = reply.send(Ok(meta.size));
                                                } else { let _ = reply.send(Ok(0)); }
                                            },
                                            _ => { let _ = reply.send(Err(libc::EIO)); }
                                        }
                                    },
                                    FsTask::Create { parent, name, mode, is_dir, reply } => {
                                        let url = if is_dir { format!("{}/mkdir{}", base_url, parent) } else { format!("{}/create{}", base_url, parent) };
                                        let res = client.post(&url).header("Authorization", format!("Bearer {}", token)).header("traceparent", &traceparent).json(&serde_json::json!({"name": name, "mode": mode})).send().await;
                                        match res {
                                            Ok(r) if r.status().is_success() => {
                                                if let Ok(meta) = r.json::<FileMeta>().await {
                                                    let _ = reply.send(Ok(meta));
                                                } else { let _ = reply.send(Err(libc::EIO)); }
                                            },
                                            _ => { let _ = reply.send(Err(libc::EIO)); }
                                        }
                                    },
                                    FsTask::Unlink { parent, name, is_dir, reply } => {
                                        let url = if is_dir { format!("{}/rmdir{}", base_url, parent) } else { format!("{}/unlink{}", base_url, parent) };
                                        let res = client.post(&url).header("Authorization", format!("Bearer {}", token)).header("traceparent", &traceparent).json(&serde_json::json!({"name": name})).send().await;
                                        match res {
                                            Ok(r) if r.status().is_success() => { let _ = reply.send(Ok(())); },
                                            _ => { let _ = reply.send(Err(libc::EIO)); }
                                        }
                                    }
                                }
                            });
                        },
                        Err(_) => break
                    }
                }
            });
        });

        let mut fs = CloudFs {
            cache,
            dir_cache,
            ino_map,
            path_map,
            next_ino,
            task_tx: tx,
        };
        fs.get_or_create_ino("/");
        fs
    }

    fn get_or_create_ino(&self, path: &str) > u64 {
        let mut path_map = self.path_map.lock().unwrap();
        if let Some(ino) = path_map.get(path) {
            return ino;
        }
        let mut next_ino = self.next_ino.lock().unwrap();
        next_ino += 1;
        let ino = next_ino;
        path_map.insert(path.to_string(), ino);
        self.ino_map.lock().unwrap().insert(ino, path.to_string());
        ino
    }

    fn get_path(&self, ino: u64) > Option<String> {
        self.ino_map.lock().unwrap().get(&ino).cloned()
    }

    fn check_cache_attr(&self, path: &str) > Option<FileMeta> {
        let cache = self.cache.lock().unwrap();
        if let Some((meta, instant)) = cache.get(path) {
            if instant.elapsed().as_secs() < 300 {
                return Some(meta.clone());
            }
        }
        None
    }

    fn insert_cache_attr(&self, path: &str, meta: FileMeta) {
        let mut cache = self.cache.lock().unwrap();
        cache.insert(path.to_string(), (meta, Instant::now()));
    }

    fn check_cache_dir(&self, path: &str) > Option<Vec<FileMeta>> {
        let cache = self.dir_cache.lock().unwrap();
        if let Some((metas, instant)) = cache.get(path) {
            if instant.elapsed().as_secs() < 300 {
                return Some(metas.clone());
            }
        }
        None
    }

    fn insert_cache_dir(&self, path: &str, metas: Vec<FileMeta>) {
        let mut cache = self.dir_cache.lock().unwrap();
        cache.insert(path.to_string(), (metas, Instant::now()));
    }

    fn meta_to_attr(&self, ino: u64, meta: &FileMeta) > FileAttr {
        FileAttr {
            ino: ino,
            size: meta.size,
            blocks: (meta.size + 511) / 512,
            atime: UNIX_EPOCH + Duration::from_secs(meta.atime),
            mtime: UNIX_EPOCH + Duration::from_secs(meta.mtime),
            ctime: UNIX_EPOCH + Duration::from_secs(meta.ctime),
            crtime: UNIX_EPOCH + Duration::from_secs(meta.ctime),
            kind: if meta.is_dir { FileType::Directory } else { FileType::RegularFile },
            perm: meta.mode,
            nlink: if meta.is_dir { 2 } else { 1 },
            uid: 1000,
            gid: 1000,
            rdev: 0,
            blksize: 512,
            flags: 0,
        }
    }

    fn build_dir_entries(&self, ino: u64, metas: &Vec<FileMeta>) > Vec<(u64, FileType, String)> {
        let mut entries: Vec<(u64, FileType, String)> = vec![(ino, FileType::Directory, ".".to_string()), (ino, FileType::Directory, "..".to_string())];
        for m in metas {
            let child_path = if m.path == "/" { format!("/{}", m.name) } else { format!("{}/{}", m.path, m.name) };
            let child_ino = self.get_or_create_ino(&child_path);
            entries.push((child_ino, if m.is_dir { FileType::Directory } else { FileType::RegularFile }, m.name.clone()));
        }
        entries
    }
}

impl Filesystem for CloudFs {
    fn lookup(&mut self, _req: &Request, parent: u64, name: &OsStr, reply: ReplyEntry) {
        let parent_path = self.get_path(parent).unwrap_or("/".to_string());
        let name_str = name.to_string_lossy().to_string();
        let path = if parent_path == "/" { format!("/{}", name_str) } else { format!("{}/{}", parent_path, name_str) };

        if let Some(meta) = self.check_cache_attr(&path) {
            let ino = self.get_or_create_ino(&path);
            let attr = self.meta_to_attr(ino, &meta);
            reply.entry(&Duration::from_secs(300), &attr, 0);
            return;
        }

        let (tx, rx) = oneshot::channel();
        self.task_tx.send(FsTask::GetAttr { path: path.clone(), reply: tx }).unwrap();
        match rx.blocking_recv() {
            Ok(Ok(meta)) => {
                self.insert_cache_attr(&path, meta.clone());
                let ino = self.get_or_create_ino(&path);
                let attr = self.meta_to_attr(ino, &meta);
                reply.entry(&Duration::from_secs(300), &attr, 0);
            },
            _ => reply.error(libc::ENOENT),
        }
    }

    fn getattr(&mut self, _req: &Request, ino: u64, reply: ReplyAttr) {
        let path = self.get_path(ino).unwrap_or("/".to_string());
        if let Some(meta) = self.check_cache_attr(&path) {
            let attr = self.meta_to_attr(ino, &meta);
            reply.attr(&Duration::from_secs(300), &attr);
            return;
        }

        let (tx, rx) = oneshot::channel();
        self.task_tx.send(FsTask::GetAttr { path: path.clone(), reply: tx }).unwrap();
        match rx.blocking_recv() {
            Ok(Ok(meta)) => {
                self.insert_cache_attr(&path, meta.clone());
                let attr = self.meta_to_attr(ino, &meta);
                reply.attr(&Duration::from_secs(300), &attr);
            },
            _ => reply.error(libc::ENOENT),
        }
    }

    fn readdir(&mut self, _req: &Request, ino: u64, _fh: u64, offset: i64, mut reply: ReplyDirectory) {
        let path = self.get_path(ino).unwrap_or("/".to_string());

        if let Some(metas) = self.check_cache_dir(&path) {
            let entries = self.build_dir_entries(ino, &metas);
            let mut i = offset as usize;
            while i < entries.len() {
                let (e_ino, kind, name) = &entries[i];
                if reply.add(e_ino, (i + 1) as i64, kind, name) { break; }
                i += 1;
            }
            reply.ok();
            return;
        }

        let (tx, rx) = oneshot::channel();
        self.task_tx.send(FsTask::ReadDir { path: path.clone(), reply: tx }).unwrap();
        match rx.blocking_recv() {
            Ok(Ok(metas)) => {
                self.insert_cache_dir(&path, metas.clone());
                let entries = self.build_dir_entries(ino, &metas);
                let mut i = offset as usize;
                while i < entries.len() {
                    let (e_ino, kind, name) = &entries[i];
                    if reply.add(e_ino, (i + 1) as i64, kind, name) { break; }
                    i += 1;
                }
                reply.ok();
            },
            _ => reply.error(libc::ENOENT),
        }
    }

    fn read(&mut self, _req: &Request, ino: u64, _fh: u64, offset: i64, size: u32, _flags: i32, _lock: Option<u64>, reply: ReplyData) {
        let path = self.get_path(ino).unwrap_or("/".to_string());
        let (tx, rx) = oneshot::channel();
        self.task_tx.send(FsTask::Read { path, offset: offset as u64, size, reply: tx }).unwrap();
        match rx.blocking_recv() {
            Ok(Ok(data)) => reply.data(&data),
            _ => reply.error(libc::EIO),
        }
    }

    fn write(&mut self, _req: &Request, ino: u64, _fh: u64, offset: i64,  &[u8], _write_flags: u32, _flags: i32, _lock: Option<u64>, reply: ReplyWrite) {
        let path = self.get_path(ino).unwrap_or("/".to_string());
        let (tx, rx) = oneshot::channel();
        self.task_tx.send(FsTask::Write { path, offset: offset as u64,  data.to_vec(), reply: tx }).unwrap();
        match rx.blocking_recv() {
            Ok(Ok(size)) => reply.written(size as u32),
            _ => reply.error(libc::EIO),
        }
    }

    fn create(&mut self, _req: &Request, parent: u64, name: &OsStr, mode: u32, _flags: u32, reply: ReplyCreate) {
        let parent_path = self.get_path(parent).unwrap_or("/".to_string());
        let name_str = name.to_string_lossy().to_string();
        let (tx, rx) = oneshot::channel();
        self.task_tx.send(FsTask::Create { parent: parent_path, name: name_str, mode, is_dir: false, reply: tx }).unwrap();
        match rx.blocking_recv() {
            Ok(Ok(meta)) => {
                let path = if meta.path == "/" { format!("/{}", meta.name) } else { format!("{}/{}", meta.path, meta.name) };
                self.insert_cache_attr(&path, meta.clone());
                let ino = self.get_or_create_ino(&path);
                let attr = self.meta_to_attr(ino, &meta);
                reply.created(&Duration::from_secs(300), &attr, 0, 0, 0);
            },
            _ => reply.error(libc::EIO),
        }
    }

    fn mkdir(&mut self, _req: &Request, parent: u64, name: &OsStr, mode: u32, reply: ReplyEntry) {
        let parent_path = self.get_path(parent).unwrap_or("/".to_string());
        let name_str = name.to_string_lossy().to_string();
        let (tx, rx) = oneshot::channel();
        self.task_tx.send(FsTask::Create { parent: parent_path, name: name_str, mode, is_dir: true, reply: tx }).unwrap();
        match rx.blocking_recv() {
            Ok(Ok(meta)) => {
                let path = if meta.path == "/" { format!("/{}", meta.name) } else { format!("{}/{}", meta.path, meta.name) };
                self.insert_cache_attr(&path, meta.clone());
                let ino = self.get_or_create_ino(&path);
                let attr = self.meta_to_attr(ino, &meta);
                reply.entry(&Duration::from_secs(300), &attr, 0);
            },
            _ => reply.error(libc::EIO),
        }
    }

    fn unlink(&mut self, _req: &Request, parent: u64, name: &OsStr, reply: ReplyEmpty) {
        let parent_path = self.get_path(parent).unwrap_or("/".to_string());
        let name_str = name.to_string_lossy().to_string();
        let path = if parent_path == "/" { format!("/{}", name_str) } else { format!("{}/{}", parent_path, name_str) };
        let (tx, rx) = oneshot::channel();
        self.task_tx.send(FsTask::Unlink { parent: parent_path, name: name_str, is_dir: false, reply: tx }).unwrap();
        match rx.blocking_recv() {
            Ok(Ok(())) => {
                self.cache.lock().unwrap().remove(&path);
                self.dir_cache.lock().unwrap().remove(&parent_path);
                reply.ok();
            },
            _ => reply.error(libc::EIO),
        }
    }

    fn rmdir(&mut self, _req: &Request, parent: u64, name: &OsStr, reply: ReplyEmpty) {
        let parent_path = self.get_path(parent).unwrap_or("/".to_string());
        let name_str = name.to_string_lossy().to_string();
        let path = if parent_path == "/" { format!("/{}", name_str) } else { format!("{}/{}", parent_path, name_str) };
        let (tx, rx) = oneshot::channel();
        self.task_tx.send(FsTask::Unlink { parent: parent_path, name: name_str, is_dir: true, reply: tx }).unwrap();
        match rx.blocking_recv() {
            Ok(Ok(())) => {
                self.cache.lock().unwrap().remove(&path);
                self.dir_cache.lock().unwrap().remove(&parent_path);
                reply.ok();
            },
            _ => reply.error(libc::EIO),
        }
    }
}

struct FsMountGuard {
    mountpoint: String,
}

impl Drop for FsMountGuard {
    fn drop(&mut self) {
        let status = std::process::Command::new("fusermount").arg("u").arg(&self.mountpoint).status();
        if status.is_err() || !status.unwrap().success() {
            let _ = std::process::Command::new("fusermount").arg("u").arg("z").arg(&self.mountpoint).status();
        }
    }
}

fn main() {
    let base_url = std::env::var("REMOTE_STORAGE_URL").expect("REMOTE_STORAGE_URL required");
    let token = std::env::var("ACCESS_TOKEN").expect("ACCESS_TOKEN required");
    let traceparent = std::env::var("TRACEPARENT").unwrap_or_default();
    let mountpoint = "/home/workdir/artifacts".to_string();

    std::fs::create_dir_all(&mountpoint).unwrap();
    let _guard = FsMountGuard { mountpoint: mountpoint.clone() };

    let fs = CloudFs::new(base_url, token, traceparent);
    fuser::mount2(fs, &mountpoint, &[]).unwrap();
}
