impl Drop for FsMountGuard {
    fn drop(&mut self) {
        let status = std::process::Command::new("fusermount").arg("u").arg(&self.mountpoint).status();
        if status.is_err() || !status.unwrap().success() {
            let _ = std::process::Command::new("fusermount").arg("u").arg("z").arg(&self.mountpoint).status();
        }
    }
}

