    finding_type: String,
    severity: String,
    details: String,
}

#[derive(Serialize, Deserialize, Debug)]
struct PerformanceMetrics {
    discovery_time_ms: u64,
    audit_time_ms: u64,
    avg_latency_us: f64,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();

    // Initialize logging
    std::env::set_var("RUST_LOG", match args.verbose {
        0 => "info",
        1 => "debug",
        _ => "trace",
    });
    env_logger::init();

    info!("Starting RDMA fabric audit");
    let start_time = SystemTime::now()
        .duration_since(UNIX_EPOCH)?
        .as_secs();

    // Step 1: Fabric Discovery
    info!("Discovering fabric topology...");
    let discovery_start = std::time::Instant::now();
    let (device_info, discovered_nodes) = discovery::discover_fabric(&args.device, args.port)?;
    let discovery_time = discovery_start.elapsed().as_millis();

    // Step 2: Security Audit
    info!("Auditing memory region protections...");
    let audit_start = std::time::Instant::now();
    let mut findings = Vec::new();
    let mut total_latency = 0.0;
    let mut successful_audits = 0;

    for node in &discovered_nodes {
        match auditor::audit_node(&args.device, args.port, node) {
            Ok(finding) => {
                findings.push(finding);
                total_latency += finding.latency_us;
                successful_audits += 1;
            }
            Err(e) => warn!("Failed to audit node {}: {}", node.lid, e),
        }
    }

    let audit_time = audit_start.elapsed().as_millis();
    let avg_latency = if successful_audits > 0 {
        total_latency / successful_audits as f64
    } else {
        0.0
    };

    // Step 3: Generate Report
    let report = AuditReport {
        timestamp: start_time,
        device_info,
        discovered_nodes,
        security_findings: findings.into_iter().map(|f| AuditFinding {
            node: f.node.clone(),
            finding_type: f.finding_type,
            severity: f.severity,
            details: f.details,
        }).collect(),
        performance_metrics: PerformanceMetrics {
            discovery_time_ms: discovery_time,
            audit_time_ms: audit_time,
            avg_latency_us: avg_latency,
        },
    };

    // Step 4: Save Report
    fs::create_dir_all(&args.output)?;
    let report_path = args.output.join(format!("rdma_audit_{}.json", start_time));
    let report_json = serde_json::to_string_pretty(&report)?;
    fs::write(&report_path, report_json)?;

    info!("Audit complete. Report saved to: {}", report_path.display());
    Ok(())
}


