use rdma_sys::*;
use std::ffi::CString;
use std::mem;
use thiserror::Error;

#[derive(Debug, Serialize, Deserialize)]
pub struct DeviceInfo {
    pub name: String,
    pub node_guid: u64,
    pub vendor_id: u32,
    pub hw_ver: u32,
    pub max_qp: u32,
    pub max_qp_wr: u32,
    pub device_cap_flags: u64,
}

#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct DiscoveredNode {
    pub lid: u16,
    pub gid: [u8; 16],
    pub qp_cap: u32,
    pub port_cap: u32,
}

#[derive(Error, Debug)]
pub enum DiscoveryError {
    #[error("Failed to open IB device: {0}")]
    DeviceOpen(String),
    #[error("Failed to query device: {0}")]
    DeviceQuery(String),
    #[error("Failed to query port: {0}")]
    PortQuery(String),
    #[error("Failed to get port GID: {0}")]
    PortGid(String),
    #[error("SM discovery failed: {0}")]
    SmDiscovery(String),
}

pub fn discover_fabric(device_name: &str, port_num: u8) -> Result<(DeviceInfo, Vec<DiscoveredNode>), DiscoveryError> {
    unsafe {
        // Open IB device
        let device_name_c = CString::new(device_name).map_err(|e| DiscoveryError::DeviceOpen(e.to_string()))?;
        let device_list = ibv_get_device_list().as_mut().ok_or_else(|| {
            DiscoveryError::DeviceOpen("Failed to get device list".to_string())
        })?;

        let mut device_ptr = std::ptr::null_mut();
        let mut i = 0;
        while !device_list[i].is_null() {
            let dev = &*device_list[i];
            let dev_name = CString::from_raw(ibv_get_device_name(dev) as *mut i8).into_string().unwrap();
            if dev_name == device_name {
                device_ptr = dev;
                break;
            }
            i += 1;
        }

        if device_ptr.is_null() {
            ibv_free_device_list(device_list);
            return Err(DiscoveryError::DeviceOpen(format!("Device {} not found", device_name)));
        }

        // Query device attributes
        let mut device_attr: ibv_device_attr = mem::zeroed();
        if ibv_query_device(device_ptr, &mut device_attr) != 0 {
            ibv_free_device_list(device_list);
            return Err(DiscoveryError::DeviceQuery("ibv_query_device failed".to_string()));
        }

        let device_info = DeviceInfo {
            name: device_name.to_string(),
            node_guid: device_attr.node_guid,
            vendor_id: device_attr.vendor_id,
            hw_ver: device_attr.hw_ver,
            max_qp: device_attr.max_qp,
            max_qp_wr: device_attr.max_qp_wr,
            device_cap_flags: device_attr.device_cap_flags,
        };

        // Query port attributes
        let mut port_attr: ibv_port_attr = mem::zeroed();
        if ibv_query_port(device_ptr, port_num, &mut port_attr) != 0 {
            ibv_free_device_list(device_list);
            return Err(DiscoveryError::PortQuery("ibv_query_port failed".to_string()));
        }

        // Get port GID
        let mut gid: ibv_gid = mem::zeroed();
        if ibv_query_gid(device_ptr, port_num, 0, &mut gid) != 0 {
            ibv_free_device_list(device_list);
            return Err(DiscoveryError::PortGid("ibv_query_gid failed".to_string()));
        }

        // Discover nodes via SM
        let mut discovered_nodes = Vec::new();

        // In a real implementation, we would use the Subnet Manager to discover nodes
        // For this example, we'll simulate discovering a few nodes
        discovered_nodes.push(DiscoveredNode {
            lid: port_attr.lid,
            gid: gid.raw,
            qp_cap: device_attr.max_qp_wr,
            port_cap: port_attr.max_msg_sz,
        });

        // Simulate discovering another node
        let mut other_gid = gid.raw;
        other_gid[15] = other_gid[15].wrapping_add(1);
        discovered_nodes.push(DiscoveredNode {
            lid: port_attr.lid + 1,
            gid: other_gid,
            qp_cap: device_attr.max_qp_wr,
            port_cap: port_attr.max_msg_sz,
        });

        ibv_free_device_list(device_list);
        Ok((device_info, discovered_nodes))
    }
}


