rust
use rdma_sys::*;
use std::ffi::CString;
use std::mem;
use std::time::Instant;
use thiserror::Error;

#[derive(Debug)]
pub struct AuditFinding {
    pub node: String,
    pub finding_type: String,
    pub severity: String,
    pub details: String,
    pub latency_us: f64,
}

#[derive(Error, Debug)]
pub enum AuditError {
    #[error("Failed to create PD: {0}")]
    PdCreation(String),
    #[error("Failed to create CQ: {0}")]
    CqCreation(String),
    #[error("Failed to create QP: {0}")]
    QpCreation(String),
    #[error("Failed to modify QP: {0}")]
    QpModify(String),
    #[error("Failed to post send: {0}")]
    PostSend(String),
    #[error("Connection failed: {0}")]
    ConnectionFailed(String),
    #[error("Memory registration failed: {0}")]
    MrRegistration(String),
}

pub fn audit_node(device_name: &str, port_num: u8, node: &crate::discovery::DiscoveredNode) -> Result<AuditFinding, AuditError> {
    unsafe {
        // Open device
        let device_name_c = CString::new(device_name).map_err(|e| AuditError::PdCreation(e.to_string()))?;
        let device_list = ibv_get_device_list().as_mut().ok_or_else(|| {
            AuditError::PdCreation("Failed to get device list".to_string())
        })?;

        let mut device_ptr = std::ptr::null_mut();
        let mut i = 0;
        while !device_list[i].is_null() {
            let dev = &*device_list[i];
            let dev_name = CString::from_raw(ibv_get_device_name(dev) as *mut i8).into_string().unwrap();
            if dev_name == device_name {
                device_ptr = dev;
                break;
            }
            i += 1;
        }

        if device_ptr.is_null() {
            ibv_free_device_list(device_list);
            return Err(AuditError::PdCreation(format!("Device {} not found", device_name)));
        }

        // Create protection domain
        let pd = ibv_alloc_pd(device_ptr);
        if pd.is_null() {
            ibv_free_device_list(device_list);
            return Err(AuditError::PdCreation("ibv_alloc_pd failed".to_string()));
        }

        // Create completion queue
        let cq = ibv_create_cq(device_ptr, 10, std::ptr::null_mut(), std::ptr::null_mut(), 0);
        if cq.is_null() {
            ibv_dealloc_pd(pd);
            ibv_free_device_list(device_list);
            return Err(AuditError::CqCreation("ibv_create_cq failed".to_string()));
        }

        // Create queue pair
        let mut qp_init_attr = ibv_qp_init_attr {
            send_cq: cq,
            recv_cq: cq,
            srq: std::ptr::null_mut(),
            cap: ibv_qp_cap {
                max_send_wr: 10,
                max_recv_wr: 10,
                max_send_sge: 1,
                max_recv_sge: 1,
                max_inline_data: 0,
            },
            qp_type: ibv_qp_type_IBV_QPT_RC,
            sq_sig_all: 1,
        };

        let qp = ibv_create_qp(pd, &mut qp_init_attr);
        if qp.is_null() {
            ibv_destroy_cq(cq);
            ibv_dealloc_pd(pd);
            ibv_free_device_list(device_list);
            return Err(AuditError::QpCreation("ibv_create_qp failed".to_string()));
        }

        // Register memory region (dummy buffer)
        let mut mr = std::ptr::null_mut();
        let buffer = libc::malloc(4096) as *mut u8;
        if buffer.is_null() {
            ibv_destroy_qp(qp);
            ibv_destroy_cq(cq);
            ibv_dealloc_pd(pd);
            ibv_free_device_list(device_list);
            return Err(AuditError::MrRegistration("Failed to allocate buffer".to_string()));
        }

        let access_flags = ibv_access_flags(
            IBV_ACCESS_LOCAL_WRITE |
            IBV_ACCESS_REMOTE_READ |
            IBV_ACCESS_REMOTE_WRITE
        );

        mr = ibv_reg_mr(
            pd,
            buffer,
            4096,
            access_flags
        );

        if mr.is_null() {
            libc::free(buffer as *mut libc::c_void);
            ibv_destroy_qp(qp);
            ibv_destroy_cq(cq);
            ibv_dealloc_pd(pd);
            ibv_free_device_list(device_list);
            return Err(AuditError::MrRegistration("ibv_reg_mr failed".to_string()));
        }

        // Get local LID
        let mut port_attr: ibv_port_attr = mem::zeroed();
        if ibv_query_port(device_ptr, port_num, &mut port_attr) != 0 {
            ibv_dereg_mr(mr);
            libc::free(buffer as *mut libc::c_void);
            ibv_destroy_qp(qp);
            ibv_destroy_cq(cq);
            ibv_dealloc_pd(pd);
            ibv_free_device_list(device_list);
            return Err(AuditError::ConnectionFailed("Failed to query port".to_string()));
        }

        let local_lid = port_attr.lid;

        // Transition QP to INIT
        let mut qp_attr = ibv_qp_attr {
            qp_state: ibv_qp_state_IBV_QPS_INIT,
            pkey_index: 0,
            port_num: port_num,
            qp_access_flags: access_flags,
            ..mem::zeroed()
        };

        if ibv_modify_qp(qp, &mut qp_attr, ibv_qp_attr_mask_IBV_QP_STATE | ibv_qp_attr_mask_IBV_QP_PKEY_INDEX | ibv_qp_attr_mask_IBV_QP_PORT | ibv_qp_attr_mask_IBV_QP_ACCESS_FLAGS) != 0 {
            ibv_dereg_mr(mr);
            libc::free(buffer as *mut libc::c_void);
            ibv_destroy_qp(qp);
            ibv_destroy_cq(cq);
            ibv_dealloc_pd(pd);
            ibv_free_device_list(device_list);
            return Err(AuditError::QpModify("Failed to modify QP to INIT".to_string()));
        }

        // Prepare connection parameters
        let mut ah_attr = ibv_ah_attr {
            is_global: 0,
            dlid: node.lid,
            sl: 0,
            src_path_bits: 0,
            port_num: port_num,
            ..mem::zeroed()
        };

        let ah = ibv_create_ah(pd, &mut ah_attr);
        if ah.is_null() {
            ibv_dereg_mr(mr);
            libc::free(buffer as *mut libc::c_void);
            ibv_destroy_qp(qp);
            ibv_destroy_cq(cq);
            ibv_dealloc_pd(pd);
            ibv_free_device_list(device_list);
            return Err(AuditError::ConnectionFailed("ibv_create_ah failed".to_string()));
        }

        // Transition QP to RTR
        qp_attr.qp_state = ibv_qp_state_IBV_QPS_RTR;
        qp_attr.path_mtu = ibv_mtu_IBV_MTU_1024;
        qp_attr.dest_qp_num = 1; // Dummy QP number
        qp_attr.rq_psn = 0;
        qp_attr.max_dest_rd_atomic = 1;
        qp_attr.min_rnr_timer = 12;

        if ibv_modify_qp(qp, &mut qp_attr, ibv_qp_attr_mask_IBV_QP_STATE | ibv_qp_attr_mask_IBV_QP_AV | ibv_qp_attr_mask_IBV_QP_PATH_MTU | ibv_qp_attr_mask_IBV_QP_DEST_QPN | ibv_qp_attr_mask_IBV_QP_RQ_PSN | ibv_qp_attr_mask_IBV_QP_MAX_DEST_RD_ATOMIC | ibv_qp_attr_mask_IBV_QP_MIN_RNR_TIMER) != 0 {
            ibv_destroy_ah(ah);
            ibv_dereg_mr(mr);
            libc::free(buffer as *mut libc::c_void);
            ibv_destroy_qp(qp);
            ibv_destroy_cq(cq);
            ibv_dealloc_pd(pd);
            ibv_free_device_list(device_list);
            return Err(AuditError::QpModify("Failed to modify QP to RTR".to_string()));
        }

        // Transition QP to RTS
        qp_attr.qp_state = ibv_qp_state_IBV_QPS_RTS;
        qp_attr.sq_psn = 0;
        qp_attr.timeout = 14;
        qp_attr.retry_cnt = 7;
        qp_attr.rnr_retry = 7;
        qp_attr.max_rd_atomic = 1;

        if ibv_modify_qp(qp, &mut qp_attr, ibv_qp_attr_mask_IBV_QP_STATE | ibv_qp_attr_mask_IBV_QP_SQ_PSN | ibv_qp_attr_mask_IBV_QP_TIMEOUT | ibv_qp_attr_mask_IBV_QP_RETRY_CNT | ibv_qp_attr_mask_IBV_QP_RNR_RETRY | ibv_qp_attr_mask_IBV_QP_MAX_QP_RD_ATOMIC) != 0 {
            ibv_destroy_ah(ah);
            ibv_dereg_mr(mr);
            libc::free(buffer as *mut libc::c_void);
            ibv_destroy_qp(qp);
            ibv_destroy_cq(cq);
            ibv_dealloc_pd(pd);
            ibv_free_device_list(device_list);
            return Err(AuditError::QpModify("Failed to modify QP to RTS".to_string()));
        }

        // Attempt RDMA READ (this will likely fail, but we're testing access controls)
        let start_time = Instant::now();
        let mut bad_wr = ibv_send_wr {
            wr_id: 0,
            next: std::ptr::null_mut(),
            sg_list: &mut ibv_sge {
                addr: buffer as u64,
                length: 4096,
                lkey: (*mr).lkey,
            },
            num_sge: 1,
            opcode: ibv_wr_opcode_IBV_WR_RDMA_READ,
            send_flags: 0,
            imm_data: 0,
            ..mem::zeroed()
        };

        // Use a dummy remote address and rkey
        unsafe {
            (*(&mut bad_wr as *mut ibv_send_wr as *mut ibv_wr_rdma)).remote_addr = 0x1000;
            (*(&mut bad_wr as *mut ibv_send_wr as *mut ibv_wr_rdma)).rkey = 0x1234;
        }

        let mut bad_wr_ptr = &mut bad_wr as *mut ibv_send_wr;
        let mut bad_wr_null = std::ptr::null_mut();

        let result = ibv_post_send(qp, bad_wr_ptr, &mut bad_wr_null);
        let latency = start_time.elapsed().as_micros() as f64;

        // Clean up
        ibv_destroy_ah(ah);
        ibv_dereg_mr(mr);
        libc::free(buffer as *mut libc::c_void);
        ibv_destroy_qp(qp);
        ibv_destroy_cq(cq);
        ibv_dealloc_pd(pd);
        ibv_free_device_list(device_list);

        // Analyze results
        let finding_type = if result == 0 {
            "UNPROTECTED_MEMORY_REGION".to_string()
        } else {
            "PROTECTED_MEMORY_REGION".to_string()
        };

        let severity = if result == 0 {
            "CRITICAL".to_string()
        } else {
            "INFO".to_string()
        };

        let details = format!(
            "RDMA READ attempt to node LID {} resulted in: {}. Latency: {:.2}μs",
            node.lid,
            if result == 0 { "SUCCESS (VULNERABLE)" } else { "FAILURE (PROTECTED)" },
            latency
        );

        Ok(AuditFinding {
            node: format!("LID:{}", node.lid),
            finding_type,
            severity,
            details,
            latency_us: latency,
        })
    }
}


