c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <infiniband/verbs.h>
#include <rdma/rdma_cma.h>
#include "discovery.h"
#include "auditor.h"
#include "reporter.h"

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <device_name> [port_num]\n", argv[0]);
        return 1;
    }

    const char *device_name = argv[1];
    int port_num = argc > 2 ? atoi(argv[2]) : 1;

    // Step 1: Discover fabric
    struct ibv_device **dev_list = ibv_get_device_list(NULL);
    if (!dev_list) {
        perror("Failed to get IB devices");
        return 1;
    }

    struct ibv_device *ib_dev = NULL;
    for (int i = 0; dev_list[i]; i++) {
        if (!strcmp(ibv_get_device_name(dev_list[i]), device_name)) {
            ib_dev = dev_list[i];
            break;
        }
    }

    if (!ib_dev) {
        fprintf(stderr, "Device %s not found\n", device_name);
        ibv_free_device_list(dev_list);
        return 1;
    }

    struct device_info dev_info;
    struct discovered_node *nodes = NULL;
    int node_count = 0;

    if (discover_fabric(ib_dev, port_num, &dev_info, &nodes, &node_count) != 0) {
        fprintf(stderr, "Fabric discovery failed\n");
        ibv_free_device_list(dev_list);
        return 1;
    }

    // Step 2: Audit nodes
    struct audit_finding *findings = malloc(node_count * sizeof(struct audit_finding));
    if (!findings) {
        perror("Failed to allocate findings");
        free(nodes);
        ibv_free_device_list(dev_list);
        return 1;
    }

    int finding_count = 0;
    for (int i = 0; i < node_count; i++) {
        if (audit_node(ib_dev, port_num, &nodes[i], &findings[finding_count]) == 0) {
            finding_count++;
        }
    }

    // Step 3: Generate report
    if (generate_report(&dev_info, nodes, node_count, findings, finding_count) != 0) {
        fprintf(stderr, "Failed to generate report\n");
    }

    // Cleanup
    free(nodes);
    free(findings);
    ibv_free_device_list(dev_list);

    return 0;
