const http = require('http');
const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');
const skillsDir = path.join(__dirname, 'skills');
const skills = {};
if (fs.existsSync(skillsDir)) {
    const files = fs.readdirSync(skillsDir);
    for (const file of files) {
        if (file.endsWith('.js')) {
            const mod = require(path.join(skillsDir, file));
            skills[file.replace('.js', '')] = mod;
        }
    }
}
function log(level, msg, traceparent) {
    console.log(JSON.stringify({
        timestamp: new Date().toISOString(),
        level: level,
        traceparent: traceparent || process.env.TRACEPARENT || '',
        message: msg
    }));
}
const server = http.createServer((req, res) => {
    let body = '';
    req.on('data', chunk => body += chunk);
    req.on('end', () => {
        let traceparent = req.headers['traceparent'] || process.env.TRACEPARENT;
        let rpcRequest;
        try {
            rpcRequest = JSON.parse(body);
        } catch (e) {
            res.writeHead(200, {'ContentType': 'application/json'});
            res.end(JSON.stringify({jsonrpc: '2.0', error: {code: 32700, message: 'Parse error'}, id: null}));
            return;
        }
        const {jsonrpc, method, params, id} = rpcRequest;
        if (method === 'initialize') {
            res.end(JSON.stringify({jsonrpc: '2.0', result: {
                protocolVersion: '20241105',
                capabilities: {tools: {}},
                serverInfo: {name: 'powersandbox', version: '2.0.0'}
            }, id}));
        } else if (method === 'tools/list') {
            const tools = Object.keys(skills).map(name => ({
                name,
                description: skills[name].description || name,
                inputSchema: skills[name].inputSchema || {type: 'object', properties: {}}
            }));
            tools.push({
                name: 'bash',
                description: 'Execute bash command with timeout',
                inputSchema: {type: 'object', properties: {command: {type: 'string'}, timeout: {type: 'integer'}}, required: ['command']}
            });
            res.end(JSON.stringify({jsonrpc: '2.0', result: {tools}, id}));
        } else if (method === 'tools/call') {
            const toolName = params.name;
            const args = params.arguments || {};
            if (toolName === 'bash') {
                const command = args.command;
                const timeout = args.timeout || 30000;
                const child = spawn('sh', ['c', command]);
                let stdout = '', stderr = '';
                child.stdout.on('data', d => stdout += d);
                child.stderr.on('data', d => stderr += d);
                setTimeout(() => child.kill('SIGKILL'), timeout);
                child.on('close', (code) => {
                    res.end(JSON.stringify({jsonrpc: '2.0', result: {
                        content: [{type: 'text', text: stdout + stderr}],
                        isError: code !== 0
                    }, id}));
                });
            } else if (skills[toolName]) {
                const result = skills[toolName].execute(args);
                res.end(JSON.stringify({jsonrpc: '2.0', result, id}));
            } else {
                res.end(JSON.stringify({jsonrpc: '2.0', error: {code: 32601, message: 'Method not found'}, id}));
            }
        }
    });
});
