        if device_list.is_null() {
            return Err(DiscoveryError::DeviceOpen("Failed to get device list".to_string()));
        }
        let mut device_ptr: mut ibv_device = std::ptr::null_mut();
        let mut i = 0;
        while !(device_list.add(i)).is_null() {
            let dev = device_list.add(i);
            let dev_name_c = ibv_get_device_name(dev);
            if !dev_name_c.is_null() {
                let dev_name = CStr::from_ptr(dev_name_c).to_string_lossy().into_owned();
                if dev_name == device_name {
                    device_ptr = dev;
                    break;
                }
            }
            i += 1;
        }
        if device_ptr.is_null() {
            ibv_free_device_list(device_list);
            return Err(DiscoveryError::DeviceOpen(format!("Device {} not found", device_name)));
        }
        let context = ibv_open_device(device_ptr);
        if context.is_null() {
            ibv_free_device_list(device_list);
            return Err(DiscoveryError::DeviceOpen(format!("Failed to open device {}", device_name)));
        }
        let mut device_attr: ibv_device_attr = mem::zeroed();
        if ibv_query_device(context, &mut device_attr) != 0 {
            ibv_close_device(context);
            ibv_free_device_list(device_list);
            return Err(DiscoveryError::DeviceQuery("ibv_query_device failed".to_string()));
        }
