            node_guid: device_attr.node_guid,
            vendor_id: device_attr.vendor_id,
            hw_ver: device_attr.hw_ver,
            max_qp: device_attr.max_qp as u32,
            max_qp_wr: device_attr.max_qp_wr as u32,
            device_cap_flags: device_attr.device_cap_flags as u64,
