        if ibv_query_port(context, port_num, &mut port_attr) != 0 {
            ibv_close_device(context);
            ibv_free_device_list(device_list);
            return Err(DiscoveryError::PortQuery("ibv_query_port failed".to_string()));
        }
        let mut gid: ibv_gid = mem::zeroed();
        if ibv_query_gid(context, port_num, 0, &mut gid) != 0 {
            ibv_close_device(context);
            ibv_free_device_list(device_list);
            return Err(DiscoveryError::PortGid("ibv_query_gid failed".to_string()));
        }
        let gid_raw = gid.raw;
        let mut discovered_nodes = Vec::new();
        discovered_nodes.push(DiscoveredNode {
            lid: port_attr.lid,
            gid: gid_raw,
            qp_cap: device_attr.max_qp_wr as u32,
            port_cap: port_attr.max_msg_sz as u32,
        });
