fn main() > Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();
    std::env::set_var("RUST_LOG", match args.verbose {
        0 => "info",
        1 => "debug",
        _ => "trace",
    });
    env_logger::init();
    info!("Starting RDMA fabric audit");
    let start_time = SystemTime::now()
        .duration_since(UNIX_EPOCH)?
        .as_secs();
    let discovery_start = Instant::now();
    let (device_info, discovered_nodes) = discover_fabric(&args.device, args.port)?;
    let discovery_time = discovery_start.elapsed().as_millis() as u64;
    let audit_start = Instant::now();
    let mut findings = Vec::new();
    let mut total_latency = 0.0;
    let mut successful_audits = 0;
    for node in &discovered_nodes {
        match audit_node(&args.device, args.port, node) {
            Ok(finding) => {
                findings.push(finding);
                total_latency += finding.latency_us;
                successful_audits += 1;
            }
            Err(e) => warn!("Failed to audit node {}: {}", node.lid, e),
        }
    }
    let audit_time = audit_start.elapsed().as_millis() as u64;
    let avg_latency = if successful_audits > 0 {
        total_latency / successful_audits as f64
    } else {
        0.0
    };
    let report = AuditReport {
        timestamp: start_time,
        device_info,
        discovered_nodes,
        security_findings: findings,
        performance_metrics: PerformanceMetrics {
            discovery_time_ms: discovery_time,
            audit_time_ms: audit_time,
            avg_latency_us: avg_latency,
        },
    };
    fs::create_dir_all(&args.output)?;
    let report_path = args.output.join(format!("rdma_audit_{}.json", start_time));
    let report_json = serde_json::to_string_pretty(&report)?;
    fs::write(&report_path, report_json)?;
    info!("Audit complete. Report saved to: {}", report_path.display());
    Ok(())
}

